          }}

events.onSubmit:
{(e) => {
              e.preventDefault();
              if (createScaleMutation.isPending) return;
              if (!newScaleTitle.trim()) {
                alert(o('titleRequired'));
                return;
              }
              createScaleMutation.mutate();
            }}

events.onClick:
{() => {
                if (currentStep === 2) {
                  if (deadlineIsPast()) {
                    setErrorMsg(c('deadlinePast'));
                    return;
                  }
                  if (!requiredAnswersPresent()) {
                    setErrorMsg(c('requiredAnswers'));
                    return;
                  }
                  if (scopeBlock && !scopeExclusionsAck) {
                    setErrorMsg(c('acknowledgeScope'));
                    return;
                  }
                  if (!characterName.trim() || !brief.trim()) {
                    setErrorMsg(c('briefRequired'));
                    return;
                  }
                }
                setErrorMsg('');
                setCurrentStep((prev) => (prev + 1) as any);
              }}

events.onSubmit:
{(event) => {
          event.preventDefault();
          if (isSaving) return;
          if (!event.currentTarget.checkValidity()) {
            setValidationError(studio('invalidBuilderNumbers'));
            event.currentTarget.reportValidity();
            return;
          }
          setValidationError('');
          onSave(blocks);
        }}

