events.onKeyDown:
{(e) => {
                                if (e.key === 'Enter') {
                                  e.preventDefault();
                                  if (!newExclusionTag.trim()) return;
                                  const next = [...(block.config.exclusions || []), newExclusionTag.trim()];
                                  updateBlockConfig(idx, { exclusions: next });
                                  setNewExclusionTag('');
                                }
                              }}

